    private static final String[] MODIFIERS={" — легкий старт"," — 10 хвилин"," — без телефону"," — з повною увагою"," — рівень PRO"};
    public static ArrayList<Quest> buildAll(){ArrayList<Quest> out=new ArrayList<>();int id=1;for(Category c:CATEGORIES){for(int i=0;i<c.bases.length;i++){for(int m=0;m<MODIFIERS.length;m++){int difficulty=m==0?1:(m<3?2:3);int minutes=5+(i%4)*5+m*5;int xp=30+difficulty*25+(i%3)*10;out.add(new Quest(id++,c.id,c.title,c.emoji,c.bases[i]+MODIFIERS[m],xp,minutes,difficulty));}}}return out;}
